"""Chapters 1-3: introduction, literature and model review, system architecture."""
from refs_aml import *
from pathlib import Path
FIG = Path(__file__).resolve().parent / 'figures'


def abstract(b, D):
    b.heading_plain('תקציר')
    b.para('בנינו מערכת תוכנה בשם Acoustic Masking Lab, שמטרתה לענות על שאלה אחת: **האם רעש תעשייתי (קידוח, הכאה, פטיש אוויר) יישאר ניתן לגילוי כשהוא מעורבב עם צלילי רקע טבעיים או סינתטיים, ומהי רמת המסכה המינימלית שנדרשת כדי להגיע ליעד גילוי שהוגדר מראש.** '
           'המערכת משלבת מודל מהיר בפייתון (ERB-EDM, מסנני גמאטון על סולם ERB, גלאי אנרגיה והסוואה לאחור בזמן) עם מודל CASP המלא מתוך Auditory Modeling Toolbox 1.6.0, שרץ ב-MATLAB ללא שינוי בחזית המודל ' + cite(PAULICK, JEPSEN, AMT) + '. '
           'סביבה זו כוללת כיול משרעת לפסקל, חישוב רמות במקלט, יצירת מסכים סינתטיים, אופטימיזציה של רמה וצורת ספקטרום, וניסויי האזנה עיוורים בשיטת 2AFC עם מדרגה אדפטיבית והתאמה פסיכומטרית.')
    b.para(f'**ממצאים עיקריים.** (א) המודל המהיר מכויל לעוגן אחד (יחס קריטי של 18 dB ב-1 kHz) ומשחזר את העלייה של היחס הקריטי עם התדר, מ-{D["cr"][0]:.1f} dB ב-250 Hz ועד {D["cr"][-1]:.1f} dB ב-8 kHz. '
           f'(ב) בבדיקה בלתי תלויה ב-4 kHz, CASP מכויל רגיש יותר מהמודל המהיר ב-{D["casp4_diff"]:.1f} dB, ולכן אי-הוודאות של ±3 dB שהוגדרה למודל המהיר אופטימית במעט. '
           '(ג) ב-AMT 1.6.0 החלק האחורי של CASP (מתאם עם תבנית והחלטה) מגיע רק לגילוי הפרשי עוצמה. לרעש מסכה נאלצנו לכייל מחדש את שונות הרעש הפנימי, מ-40 ל-' + f'{D["invar"]:.0f}' + ', ולדווח את שתי הגרסאות. '
           f'(ד) בהכאה סינתטית של 60 dBA עם גורם שיא של כ-{D["crest"]:.0f} dB, רמת המסכה הנדרשת נקבעת על ידי **שיאי** הרעש ולא על ידי LAeq: נדרש רעש ורוד של {D["pink06"]:.0f} dBA, כלומר הרבה מעל רמת הרעש עצמו. '
           '(ה) מסכים טבעיים שהספקטרום שלהם יורד בתדרים הגבוהים (רוח, מים) דורשים רמות גבוהות בהרבה מרעש ורוד, כי האנרגיה של הרעש התעשייתי נמצאת בתדרים בינוניים וגבוהים.')
    b.para('**הערת שקיפות.** המטרות והמסכים בדוגמאות הם סינתטיים ומסומנים ככאלה. לא נאספו נתוני שדה ולא נתוני מאזינים אמיתיים; מנגנון הניסוי נבדק עם מאזין מדומה. '
           'כל מה שלא אומת (למשל מדדי הנעימות והרעש הנתפס) מסומן כאומדן יחסי.')


def ch1(b, D):
    b.chapter('מבוא, מטרות והגדרת הבעיה', 'ch1')
    b.section('מה שואלים')
    b.para('פעילות תעשייתית רועשת במרחק של עשרות מטרים משכנים יוצרת במקלט רמות שאינן בהכרח גבוהות, אבל הן עשויות להישמע. הפתרון הרגיל הוא הנחתה במקור או במסלול. בעבודה זו בחנו פתרון משלים: **להוסיף צליל רקע** כך שהרעש התעשייתי יאבד את ייחודו התפיסתי. '
           'השאלה הכמותית היא איזו רמה, ובאיזה ספקטרום, נדרשות כדי שהמטרה לא תהיה ניתנת לגילוי מעל יעד שנקבע, וכמה צליל נוסף המסכה מוסיפה לסביבה.')
    b.para('חשוב להבהיר מראש את הגבול של הגישה. מסכה **אינה מפחיתה** את הרעש; היא מוסיפה צליל. גם כשהיא מורידה את הגילוי, היא יכולה להעלות את הרעש הנתפס. לכן כל הדוחות של המערכת מציגים בנפרד את הרמה המוספת (dBA) ואת מדדי הקול והמטרד, ואין בהם הבטחה של "אי-שמיעות" אלא הערכה עם אי-ודאות.')
    b.section('ארבעה מושגים שהמערכת מפרידה ביניהם')
    b.table(['מושג', 'מה זה', 'מה המערכת עושה איתו'], [
        ['Energetic masking', 'אנרגיית המסכה באותו מסנן שמיעתי ובאותו חלון זמן מסתירה את המטרה', 'מנבאת (ERB-EDM, CASP)'],
        ['Detectability', 'האם מאזין יכול לדעת שהמטרה קיימת (2AFC, $d\'$)', 'מנבאת ומודדת בניסוי'],
        ['Attentional distraction', 'צלילים בולטים לוכדים קשב גם כשהם מוסתרים', 'לא מנבאת; מצוין כמגבלה'],
        ['Annoyance', 'שיפוט של אי-נעימות לאורך זמן', 'מדווחת כאומדן יחסי בלבד (proxy)'],
    ], caption='הפרדה בין ארבעה מושגים שהמערכת מתייחסת אליהם', label='tab_constructs', widths=[3.6, 7.2, 5.4])
    b.para('Informational masking, כלומר הסוואה שנובעת מדמיון או מאי-ודאות של המאזין ולא מחפיפה אנרגטית ' + cite(DURLACH) + ', אינה חלק מהמודלים כאן. הרעש התעשייתי המוכר (מטרה ידועה, חוזרת) מקטין את האי-ודאות, ולכן הערכה אנרגטית היא בדרך כלל זהירה, אך לא תמיד.')
    b.section('דרישות המערכת')
    b.bullets([
        'קלט: WAV של לחץ אקוסטי ב-Pa לאורך הזמן, תדר דגימה ומרחק מיקרופון (ברירת מחדל 7 m), כיול משרעת, חיסור רעש רקע, בדיקת צורת גל וספקטרום (אוקטבה ושליש אוקטבה).',
        'מסכים: WAV מותאם אישית או סינתזה של רוח, צרצרים, מים זורמים, גשם, עלים ורעש לבן, ורוד וחום, עם עיצוב ספקטרלי, שונות בזמן ורמות.',
        'חיזוי: ערבוב ברמות פיזיקליות במקלט, גילוי כפונקציה של SNR וסוג מסכה, רמת מסכה מינימלית ליעד גילוי עם אי-ודאות, השוואה בין טבעי לסינתטי.',
        'ניסויים: השמעה מכוילת וצפויה בטיחותית, 2AFC עיוור, מדרגות אדפטיביות, התאמה פסיכומטרית, סף אישי והשוואה למודל.',
        'פלטים: דשבורד אינטראקטיבי, ייצוא WAV, CSV, Excel ו-PDF, ותצורות שחוזרות על עצמן.',
    ])
    b.section('מבנה המסמך')
    b.para('פרק 2 סוקר ספרות ומודלים, פרק 3 את הארכיטקטורה, ופרקים 4 עד 7 את הקלט, המסכים, המודל המהיר והגשר ל-CASP. פרקים 8 ו-9 מציגים חיזוי, אופטימיזציה וניסויי האזנה, פרקים 10 ו-11 את הממשק ואת בקרת האיכות, ופרק 12 את המגבלות.')


def ch2(b, D):
    b.chapter('סקירת ספרות ומודלים', 'ch2')
    b.para('הסקירה מבוססת על מקורות שאומתו בחיפוש מקוון (פרטי הפרסום והמספר המזהה, DOI, שבהם נמצא). מקורות שהפרטים שלהם לא אומתו במלואם מסומנים כך ברשימה הביבליוגרפית. לא קראנו את כל המאמרים במלואם; כשהטענה נשענת על תקציר בלבד נאמר זאת.')
    b.section('מסנני שמיעה, סולם ERB וגמאטון')
    b.para('המסנן השמיעתי מתואר כמסנן עם רוחב פס שקול מלבני (ERB). Glasberg ו-Moore ' + cite(GLASBERG) + ' נתנו קירוב לרוחב כפונקציה של התדר, '
           '$\\mathrm{ERB}(f)=24.7\\,(4.37\\,f/1000+1)$ ב-Hz, ואת סולם מספרי ה-ERB $E=21.4\\lg(4.37\\,f/1000+1)$ שבו כל יחידה היא רוחב מסנן אחד. '
           'מסנן הגמאטון הוא הקירוב הנפוץ לתגובת הקרום הבסיסי ' + cite(PATTERSON) + ', ו-Hohmann ' + cite(HOHMANN) + ' תיאר מימוש דיגיטלי יציב כמסנן חד-קוטבי מרוכב מדורג.')
    b.para('מימשנו מסנן גמאטון מסדר 4 על פני 36 ערוצים בין 50 Hz ל-12,000 Hz במרווח של ERB אחד, כמדורג של ארבעה מסנני קוטב מרוכבים עם $b=1.019\\,\\mathrm{ERB}$ (ראו פרק 6).')
    b.section('הסוואה בו-זמנית והסוואה בזמן')
    b.para('Hawkins ו-Stevens ' + cite(HAWKINS) + ' מדדו את היחס הקריטי: היחס בין עוצמת הטון להספק הרעש הלבן לכל Hz בסף ההסוואה. ערכו ב-1 kHz הוא סביב 18 dB, וכך עיגנו את הכיול שלנו. '
           'ההסוואה לאחור בזמן (forward masking) פוחתת עם ההשהיה בין המסכה לבדיקה, ועם הרמה, כפי שהראו Jesteadt ו-Bacon ו-Lehman ' + cite(JESTEADT) + '. '
           'אינטגרציה בזמן של רגישות לצלילים קצרים תוארה על ידי Plomp ו-Bouman ' + cite(PLOMP) + ': סף הגילוי יורד ככל שהצליל ארוך יותר, עד קבוע זמן של סדר גודל של מאות ms.')
    b.section('מודולציה, CASP ו-AMT')
    b.para('מודלי המודולציה של קבוצת Dau ' + cite(DAU97) + ' מוסיפים לסינון האודיו שלב של סינון מודולציה על המעטפת, ו-Ewert ו-Dau ' + cite(EWERT) + ' הראו שמודל ספק מעטפת (EPSM) מסביר רגישות לתנודות מעטפת. '
           'Jepsen ו-Ewert ו-Dau ' + cite(JEPSEN) + ' בנו על כך את CASP: עיבוד עורף-אוזן, מסנני DRNL, תמלול תאי שיער, לולאות הסתגלות, מסנני מודולציה ושלב החלטה עם רעש פנימי. '
           'גרסה מעודכנת, Paulick ואחרים ' + cite(PAULICK) + ', מחליפה את מסנני הגמאטון הליניאריים ב-DRNL לא ליניארי, משנה את שלב תאי השיער ומוסיפה בחירת ערוצים אוטומטית. '
           'ה-Auditory Modeling Toolbox ' + cite(AMT) + ' כולל את המימוש (`paulick2024`) והוא זה שהפעלנו, יחד עם `demo_paulick2024` ששימש לנו כמקור לאופן שבו החלק האחורי בנוי.')
    b.callout('warning', 'הערת AMT על המימוש: הקוד מציין שגרסת 2008 ממומשת "עד כמה שאפשר" לפי תיאור מוגבל במאמר, ושהמיקוד הוא בגרסת 2024. '
              'מימוש Python של המודל (ספריית torch-amt) הוא פרויקט צד שלישי ולא נבדק על ידינו.')
    b.section('תורת זיהוי האות ומבחני 2AFC')
    b.para('גילוי מנוסח באמצעות תורת זיהוי האות ' + cite(GREEN) + ': בכל ניסיון המאזין מקבל משתנה החלטה, ו-$d\'$ הוא מרחק ההתפלגויות ביחידות סטיית תקן. ב-2AFC עם שני מרווחים בלתי תלויים, ההסתברות לבחירה נכונה היא '
           '$P=\\Phi(d\'/\\sqrt{2})$ ' + cite(GREEN) + '. מדרגה n-down/1-up מתכנסת לנקודה על הפונקציה הפסיכומטרית: 70.7% ל-2-down/1-up ו-79.4% ל-3-down/1-up ' + cite(LEVITT) + '. התאמת הפונקציה הפסיכומטרית ואומדן רווחי סמך נעשים כפי שהומלץ אצל Wichmann ו-Hill ' + cite(WICHMANN) + '.')
    b.section('הסוואת רעש תעשייתי בצלילי טבע')
    b.para('Hong ואחרים ' + cite(HONG) + ' בחנו בניסוי מעבדה הוספה של ציוץ ציפורים וקול נחל לרעש של פטיש הידראולי ולרעש תנועה ברמות של 55, 65 ו-75 dB(A). נמצא שהוספת הצלילים הטבעיים הורידה את העוצמה הנתפסת של הרעש. '
           'עבודה זו בדקה **הערכה סובייקטיבית** (עוצמה נתפסת ואיכות הנוף הקולי), לא סף גילוי. Jeon ואחרים ' + cite(JEON) + ' מצאו שצלילי מים הם המסכה המומלצת לשיפור הנוף הקולי העירוני, ושרמתם צריכה להיות דומה לרמת הרעש או נמוכה ממנה בלא יותר מ-3 dB. '
           'Smyrnova ו-Brown ' + cite(SMYRNOVA) + ' בחנו את האינטראקציה בין תפיסה שמיעתית וחזותית של רעש תעשייתי (לא קראנו את הטקסט המלא). '
           'מכאן שהספרות שמצאנו תומכת בהפחתת הרעש הנתפס ובשיפור הנוף הקולי, ואינה קובעת סף גילוי. זהו בדיוק הפער שהמערכת באה למלא.')
    b.section('מגבלות תחולה של המודלים')
    b.table(['מודל', 'מה הוא מנבא', 'הנחות', 'מגבלה'], [
        ['ERB-EDM (העבודה הזו)', 'גילוי מטרה ידועה במסכה', 'גלאי אנרגיה אופטימלי בין ערוצים; הסוואה לאחור; רצפת רעש לפי סף השמיעה', 'מכויל לעוגן אחד; אין עיבוד מודולציה מפורש'],
        ['CASP / paulick2024', 'גילוי לפי תבנית פנימית אחרי DRNL, הסתגלות ומודולציה', 'מאזין עם שמיעה תקינה; רעש פנימי קבוע', 'החלק האחורי של AMT נבדק רק להבדלי עוצמה; איטי'],
        ['EPSM', 'גילוי לפי תנודות מעטפת', 'מסנני מודולציה', 'לא ממומש כאן בנפרד'],
        ['מדדי קול (N5, S, F, PA)', 'עוצמה, חדות ותנודה', 'כיול לגירויי ייחוס', 'אינם תקן ISO 532'],
    ], caption='מודלים ומגבלות התחולה שלהם', label='tab_models', widths=[3.4, 4.0, 4.8, 4.0])


def ch3(b, D):
    b.chapter('ארכיטקטורה של המערכת', 'ch3')
    b.para('המערכת מפרידה בין שכבות כדי שניתן יהיה לבדוק כל אחת לבד. {ref:fig_arch} מציג אותן, ו{ref:tab_layers} מפרט את תפקידי המודולים.')
    b.fig(FIG / 'system' / 'fig_architecture', 'ארכיטקטורת המערכת: דפדפן, API, חמש שכבות חישוב וגשר ל-MATLAB.', 'fig_arch')
    b.table(['שכבה', 'מודול', 'תפקיד'], [
        ['עיבוד שמע', 'units, audio_io, spectra', 'יחידות ורמות, A-weighting לפי IEC 61672-1, כיול, דגימה מחדש, חיסור רקע, ספקטרה'],
        ['יצירת קול', 'generators', 'רוח, צרצרים, מים, גשם, עלים, רעש לבן/ורוד/חום, עיצוב ספקטרלי, שונות בזמן, מטרות סינתטיות'],
        ['מודלים', 'fastmodel, casp_bridge, loudness', 'ERB-EDM, הרצת CASP ב-MATLAB, מדדי עוצמה ומטרד'],
        ['אופטימיזציה', 'optimize', 'רמה מינימלית ליעד גילוי, צורת ספקטרום, אי-ודאות'],
        ['ניסויים', 'experiments', '2AFC, מדרגות, התאמה פסיכומטרית, מגבלות בטיחות'],
        ['הצגה', 'app.py + frontend', 'API, דשבורד, דוחות'],
    ], caption='שכבות המערכת ותפקידי המודולים', label='tab_layers', widths=[3.0, 4.6, 8.6])
    b.section('יחידות וכללי עבודה')
    b.bullets([
        'אותות לחץ ב-**Pa**, רמת ייחוס 20 µPa. "רמה במקלט" היא רמת לחץ פיזית בעמדת המאזין; "רמת השמעה" היא רמה בצימוד אוזניות. שתי הכמויות אינן מתבלבלות לאורך הקוד.',
        'כל אקראיות נגזרת מזרע דטרמיניסטי (seed), כך שתצורה אחת נותנת תוצאה זהה בכל הרצה.',
        'כל תוצאה מסומנת במודל שיצר אותה; תוצאת CASP מוצגת רק אם הורץ הקוד של AMT.',
        'סביבת Python מוגדרת מחוץ ל-OneDrive: `%LOCALAPPDATA%\\AcousticMaskingLab\\venv`, וה-node_modules הועברו אליה דרך junction.',
    ])
    b.section('זרימת נתונים')
    b.para('המטרה נטענת, מכוילת ל-Pa, מוצבת מחדש במרחק המקלט, מנוקה מרקע ומוגבלת לחלון אירוע של עד 10 s. כל מסכה מרונדרת לאותו אורך וברמה שהוגדרה. '
           'שני האותות עוברים סינון ERB פעם אחת בלבד, והמודל המהיר מחשב אחר כך את הגילוי לכל רמת מטרה או מסכה בלי סינון חוזר; זו הסיבה שאפשר להציג עקומות גילוי בזמן אמת. '
           'CASP רץ כמשימת רקע, ומחזיר הסתברויות לרמות המסכה שנבחרו.')
